// ============================================
// PREDICTION ENGINE
// Takes team stats and generates the best bets
// ============================================

export function generatePrediction(homeTeam, awayTeam, homeStats, awayStats) {
    // 1. Calculate a "Strength Score" for each team
    const homeStrength = calculateStrength(homeStats);
    const awayStrength = calculateStrength(awayStats);

    // 2. Match Result Prediction (1X2)
    let matchResult = 'Draw';
    if (homeStrength > awayStrength * 1.2) {
        matchResult = 'Home Win';
    } else if (awayStrength > homeStrength * 1.2) {
        matchResult = 'Away Win';
    }

    // 3. Over/Under 2.5 Goals Prediction
    const homeGoals = homeStats?.goalsFor || 0;
    const awayGoals = awayStats?.goalsFor || 0;
    const totalAvgGoals = (homeGoals + awayGoals) / 2;

    let overUnder = 'Under 2.5';
    if (totalAvgGoals > 2.5) {
        overUnder = 'Over 2.5';
    }

    // 4. Both Teams to Score (BTTS)
    const homeScored = homeGoals >= 1;
    const awayScored = awayGoals >= 1;
    let btts = 'No';
    if (homeScored && awayScored) {
        btts = 'Yes';
    }

    // 5. Hybrid Twist (10% chance to change one prediction)
    // This keeps it unpredictable and fun
    const random = Math.random();
    if (random < 0.1) {
        matchResult = matchResult === 'Home Win' ? 'Draw' : matchResult === 'Draw' ? 'Away Win' : 'Home Win';
    } else if (random < 0.2) {
        overUnder = overUnder === 'Over 2.5' ? 'Under 2.5' : 'Over 2.5';
    } else if (random < 0.3) {
        btts = btts === 'Yes' ? 'No' : 'Yes';
    }

    // 6. Generate a confidence score (Low, Medium, High)
    const confidence = calculateConfidence(homeStrength, awayStrength, homeStats, awayStats);

    return {
        matchResult,
        overUnder,
        btts,
        confidence
    };
}

// Helper: Calculate Strength from team stats
function calculateStrength(stats) {
    if (!stats) return 50; // Default if no data

    const played = stats.played || 1;
    const winRate = (stats.won || 0) / played;
    const goalDiff = (stats.goalsFor || 0) - (stats.goalsAgainst || 0);
    const points = stats.points || 0;

    // Weighted formula
    const strength = (winRate * 40) + (points * 0.5) + (goalDiff * 2);
    return Math.max(10, Math.min(90, strength)); // Clamp between 10-90
}

// Helper: Calculate confidence level
function calculateConfidence(homeStrength, awayStrength, homeStats, awayStats) {
    const strengthDiff = Math.abs(homeStrength - awayStrength);
    
    if (strengthDiff > 30) return 'High';
    if (strengthDiff > 15) return 'Medium';
    return 'Low';
}
